import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_opp = opp[-1]
    last_me = me[-1]

    # Early game: establish cooperation; retaliate once against early defection.
    if n <= 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Classify opponent using a long window and a short window.
    long_w = min(30, n)
    long_recent = opp[-long_w:]
    long_coop = long_recent.count('C') / float(long_w)

    short_w = min(8, n)
    short_recent = opp[-short_w:]
    short_coop = short_recent.count('C') / float(short_w)

    # Detect runs of opponent defection.
    def opp_streak():
        s = 0
        for a in reversed(opp):
            if a == 'D':
                s += 1
            else:
                break
        return s

    streak = opp_streak()

    # Very defection-heavy opponent: defect, with rare probing.
    if long_coop < 0.25:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Moderately defection-heavy: defect mostly, cooperate when they cooperate.
    if long_coop < 0.5:
        if streak >= 2:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if last_opp == 'C':
            # reciprocate cooperation but avoid being exploited
            if short_coop > 0.4:
                return 'C'
            return 'D' if rng.random() < 0.4 else 'C'
        return 'D'

    # Cooperative opponent (long_coop >= 0.5).
    # Exploit very cooperative opponents mildly, but avoid destabilizing.
    if long_coop >= 0.85 and n >= 15:
        # Rare probing defect if we've been cooperating a lot.
        if last_opp == 'C' and last_me == 'C':
            if rng.random() < 0.10:
                return 'D'
        # Endgame exploitation.
        if n >= 90:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if n >= 80 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Mid-cooperative: tit-for-tat with forgiveness.
    if last_opp == 'D':
        if streak >= 3:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        return 'D'
    else:
        # Opponent cooperated.
        # If prior round we defected and got away with it, sometimes continue exploiting.
        if last_me == 'D' and short_coop > 0.7 and long_coop > 0.75:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        # Small chance to probe a very nice opponent.
        if short_coop >= 0.875 and long_coop >= 0.8 and rng.random() < 0.08:
            return 'D'
        return 'C'
